import 'dart:typed_data';

import 'package:crypto/crypto.dart';

const String agentMcpVersion = '3.5.3';

const String appIconSvg =
    '<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64">'
    '<defs>'
    '<linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">'
    '<stop offset="0%" stop-color="#161838"/>'
    '<stop offset="100%" stop-color="#090A16"/>'
    '</linearGradient>'
    '<radialGradient id="aura" cx="0.68" cy="0.70" r="0.52">'
    '<stop offset="0%" stop-color="#4F46E5" stop-opacity="0.56"/>'
    '<stop offset="100%" stop-color="#4F46E5" stop-opacity="0"/>'
    '</radialGradient>'
    '<linearGradient id="pBack" x1="0" y1="0" x2="1" y2="1">'
    '<stop offset="0%" stop-color="#939EFF"/>'
    '<stop offset="100%" stop-color="#4F46E5"/>'
    '</linearGradient>'
    '<linearGradient id="pFront" x1="0" y1="0" x2="1" y2="1">'
    '<stop offset="0%" stop-color="#FFFFFF"/>'
    '<stop offset="100%" stop-color="#DFE6FF"/>'
    '</linearGradient>'
    '</defs>'
    '<rect x="2" y="2" width="60" height="60" rx="15" fill="url(#bg)" stroke="#818CF8" stroke-opacity="0.28" stroke-width="1"/>'
    '<rect x="2" y="2" width="60" height="60" rx="15" fill="url(#aura)"/>'
    '<path fill="url(#pBack)" fill-rule="evenodd" d="M35.6 18.2a3.2 3.2 0 0 1 4.5 0l12.7 12.7a3.2 3.2 0 0 1 0 4.5L40.1 48.1a3.2 3.2 0 0 1-4.5 0L22.9 35.4a3.2 3.2 0 0 1 0-4.5Z M36.6 26.2a1.8 1.8 0 0 1 2.5 0l5.7 5.7a1.8 1.8 0 0 1 0 2.5l-5.7 5.7a1.8 1.8 0 0 1-2.5 0l-5.7-5.7a1.8 1.8 0 0 1 0-2.5Z"/>'
    '<path fill="url(#pFront)" fill-rule="evenodd" d="M26.9 11.4a3.4 3.4 0 0 1 4.8 0l13.9 13.9a3.4 3.4 0 0 1 0 4.8L31.7 44.0a3.4 3.4 0 0 1-4.8 0L13.0 30.1a3.4 3.4 0 0 1 0-4.8Z M28.0 19.9a1.9 1.9 0 0 1 2.6 0l6.3 6.3a1.9 1.9 0 0 1 0 2.6l-6.3 6.3a1.9 1.9 0 0 1-2.6 0l-6.3-6.3a1.9 1.9 0 0 1 0-2.6Z"/>'
    '</svg>';

final String appIconDataUri =
    'data:image/svg+xml;base64,${base64Encode(utf8.encode(appIconSvg))}';

/// Exact 48x48, 64x64 & 128x128 RGBA Concentric Liquid Prism PNGs (synced by `scripts/sync_brand_icons.py`).
/// Placed FIRST as self-contained `data:image/png;base64,...` URIs so strict-CSP web MCP hosts
/// (`gemini.google.com`, `claude.ai`, `chatgpt.com`) render brand icons immediately without third-party `img-src` blocks.
const String appIconPng48Base64 = '';
const String appIconPng64Base64 = '';
const String appIconPng128Base64 = '';

final Uint8List appIconPng64Bytes = base64Decode(appIconPng64Base64);
final Uint8List appIconPng48Bytes = appIconPng48Base64.isNotEmpty
    ? base64Decode(appIconPng48Base64)
    : appIconPng64Bytes;
final Uint8List appIconPng128Bytes = appIconPng128Base64.isNotEmpty
    ? base64Decode(appIconPng128Base64)
    : appIconPng64Bytes;

const String appIconPng48DataUri = 'data:image/png;base64,$appIconPng48Base64';
const String appIconPngDataUri = 'data:image/png;base64,$appIconPng64Base64';
const String appIconPng128DataUri = 'data:image/png;base64,$appIconPng128Base64';

/// Builds the full MCP-spec-compliant `icons` array (`2025-11-25` SEP-973 & `2026-07-28`).
///
/// Self-contained `data:image/png;base64,...` URIs ALWAYS lead (`icons[0..]`) ahead of any external URL
/// so strict browser CSP policies (`img-src 'self' data:` on `gemini.google.com` / `claude.ai`) never block
/// `icons[0]`, while `appIconSvg` carries explicit `width="64" height="64"` for SVG-preferring hosts.
List<Map<String, dynamic>> buildMcpServerIcons({
  String? baseUrl,
  bool compact = false,
}) {
  if (compact) {
    return <Map<String, dynamic>>[
      if (appIconPng48Base64.isNotEmpty)
        {
          'src': appIconPng48DataUri,
          'mimeType': 'image/png',
          'sizes': const ['48x48'],
        }
      else if (appIconPng64Base64.isNotEmpty)
        {
          'src': appIconPngDataUri,
          'mimeType': 'image/png',
          'sizes': const ['64x64'],
        },
      {
        'src': appIconDataUri,
        'mimeType': 'image/svg+xml',
        'sizes': const ['64x64', 'any'],
      },
    ];
  }

  final cleanBase = (baseUrl ?? '').trim().replaceAll(RegExp(r'/+$'), '');
  final hasHttpsBase = cleanBase.toLowerCase().startsWith('https://');
  return <Map<String, dynamic>>[
    if (appIconPng64Base64.isNotEmpty)
      {
        'src': appIconPngDataUri,
        'mimeType': 'image/png',
        'sizes': const ['64x64'],
      },
    if (appIconPng128Base64.isNotEmpty)
      {
        'src': appIconPng128DataUri,
        'mimeType': 'image/png',
        'sizes': const ['128x128'],
      },
    if (appIconPng48Base64.isNotEmpty)
      {
        'src': appIconPng48DataUri,
        'mimeType': 'image/png',
        'sizes': const ['48x48'],
      },
    if (appIconPng64Base64.isNotEmpty) ...[
      {
        'src': appIconPngDataUri,
        'mimeType': 'image/png',
        'sizes': const ['64x64'],
        'theme': 'dark',
      },
      {
        'src': appIconPngDataUri,
        'mimeType': 'image/png',
        'sizes': const ['64x64'],
        'theme': 'light',
      },
    ],
    {
      'src': appIconDataUri,
      'mimeType': 'image/svg+xml',
      'sizes': const ['64x64', 'any'],
    },
    if (hasHttpsBase)
      {
        'src': '$cleanBase/icon-192.png',
        'mimeType': 'image/png',
        'sizes': const ['192x192'],
      },
  ];
}

/// Converts an arbitrary human display name into a strict MCP `Implementation.name` slug.
String sanitizeMcpMachineName(String raw) {
  final trimmed = raw.trim();
  if (trimmed.isEmpty) return 'agent-mcp';
  final slug = trimmed
      .replaceAll(RegExp(r'[^a-zA-Z0-9._-]+'), '-')
      .replaceAll(RegExp(r'^-+|-+$'), '');
  if (slug.isNotEmpty && RegExp(r'[a-zA-Z0-9]').hasMatch(slug)) {
    return slug.length > 64 ? slug.substring(0, 64) : slug;
  }
  final h6 = sha256.convert(utf8.encode(trimmed)).toString().substring(0, 6);
  return 'agent-mcp-$h6';
}
